# ---------------- cell 6 ----------------
from sklearn.manifold import TSNE

tsne = TSNE(
    n_components=2,
    perplexity=20,        
    learning_rate="auto", 
    init="pca",           
    n_iter=500,          
    early_exaggeration=12,
    random_state=42,
    metric="euclidean"    
)
is_3b = events_tst_CR_random.is_3b
is_bg4b = events_tst_CR_random.is_bg4b
is_signal = events_tst_CR_random.is_signal


# ---------------- cell 7 ----------------
features_embedded = tsne.fit_transform(features_CR)
repr_embedded = tsne.fit_transform(q_repr_CR.reshape(-1, q_repr_CR.shape[1] * q_repr_CR.shape[2]))


# ---------------- cell 8 ----------------
fig, ax = plt.subplots(1, 2, figsize=(10, 5))

ax[0].set_title("t-SNE of the original space", fontsize=20)
