ax[0].scatter(features_embedded[is_bg4b, 0], features_embedded[is_bg4b, 1], label=r"Background $4b$", s=2, rasterized=True)
ax[0].scatter(features_embedded[is_signal, 0], features_embedded[is_signal, 1], label=r"$\mathrm{HH} \to 4b$", s=30, rasterized=True)
ax[0].legend(loc="lower right", fontsize=15)

ax[1].set_title("t-SNE of the representation space", fontsize=20)    
ax[1].scatter(repr_embedded[is_3b, 0], repr_embedded[is_3b, 1], label=r"$3b$", s=2, rasterized=True)
ax[1].scatter(repr_embedded[is_bg4b, 0], repr_embedded[is_bg4b, 1], label=r"Background $4b$", s=2, rasterized=True)
ax[1].scatter(repr_embedded[is_signal, 0], repr_embedded[is_signal, 1], label=r"$\mathrm{HH} \to 4b$", s=30, rasterized=True)
ax[1].legend(loc="lower right", fontsize=15)

